# Generated by test-lab — blind adversarial evaluation
"""Typer command tests using real files and the production render/validate pipeline."""

import hashlib
import json
from pathlib import Path

from typer.testing import CliRunner

from create_svg.cli import app

RUNNER = CliRunner()


def test_new_render_and_validate(tmp_path: Path) -> None:
    scene = tmp_path / "scene.yml"
    svg = tmp_path / "scene.svg"
    receipt = tmp_path / "receipt.json"

    created = RUNNER.invoke(app, ["new", "positive-negative", str(scene)])
    assert created.exit_code == 0, created.output

    rendered = RUNNER.invoke(app, ["render", str(scene), str(svg)])
    assert rendered.exit_code == 0, rendered.output
    assert svg.exists()

    validated = RUNNER.invoke(app, ["validate", str(svg), "--receipt", str(receipt)])
    assert validated.exit_code == 0, validated.output
    assert '"status": "PASS"' in receipt.read_text(encoding="utf-8")


def test_unsafe_cli_returns_nonzero() -> None:
    fixture = Path(__file__).parent / "fixtures" / "unsafe-script.svg"
    result = RUNNER.invoke(app, ["validate", str(fixture)])
    assert result.exit_code == 1
    assert '"status": "FAIL"' in result.output


def test_visual_gate_binds_reviewer_to_exact_screenshot(tmp_path: Path) -> None:
    svg = tmp_path / "card.svg"
    screenshot = tmp_path / "card.png"
    receipt = tmp_path / "visual-gate.json"
    svg.write_text('<svg xmlns="http://www.w3.org/2000/svg"><title>x</title></svg>', encoding="utf-8")
    screenshot.write_bytes(b"\x89PNG\r\n\x1a\nreal screenshot bytes")
    digest = hashlib.sha256(screenshot.read_bytes()).hexdigest()

    result = RUNNER.invoke(
        app,
        [
            "visual-gate",
            str(svg),
            str(screenshot),
            "--receipt",
            str(receipt),
            "--target",
            "project-card",
            "--target-size",
            "400x260",
            "--goal",
            "represent Tau",
            "--reviewer",
            "claude-fable-low",
            "--inspected-screenshot-sha256",
            digest,
            "--inspected-screenshot-path",
            str(screenshot),
            "--represents-goal",
            "--attractive",
        ],
    )

    assert result.exit_code == 0, result.output
    payload = json.loads(receipt.read_text(encoding="utf-8"))
    assert payload["kind"] == "create_svg.visual_gate.v1"
    assert payload["status"] == "PASS"
    assert payload["screenshot_sha256"] == digest


def test_tau_variant_loop_receipt_has_concurrent_creator_command_and_codes(tmp_path: Path) -> None:
    variants = tmp_path / "variants.yml"
    receipt = tmp_path / "plan.json"
    variants.write_text(
        """
schema: create_svg.variant_pack.v1
variants:
  - id: ledger-first
    direction: Make signed receipts visually dominant.
  - id: dag-first
    direction: Make DAG nodes visually dominant.
""".lstrip(),
        encoding="utf-8",
    )

    result = RUNNER.invoke(
        app,
        [
            "tau-variant-loop",
            str(variants),
            "--goal",
            "Tau is a zero-trust DAG execution harness.",
            "--target",
            "grahama.co Tau project card",
            "--target-size",
            "400x260",
            "--screenshot-command",
            "skills/surf/run.sh screenshot --out <SCREENSHOT_PATH>",
            "--receipt",
            str(receipt),
            "--creator-handler",
            "gpt-5.5-high",
            "--creator-handler",
            "webkimi",
            "--judge-handler",
            "claude-fable-low",
            "--ask-id",
            "unit-variant-loop",
            "--run-output-root",
            str(tmp_path / "runs"),
        ],
    )

    assert result.exit_code == 0, result.output
    payload = json.loads(receipt.read_text(encoding="utf-8"))
    assert payload["kind"] == "create_svg.tau_variant_loop_plan.v1"
    assert payload["creator_handlers"] == ["gpt-5.5-high", "webkimi"]
    assert payload["judge_handler"] == "claude-fable-low"
    assert payload["active_failure_code"] is None
    assert payload["ask_command"][:3] == [
        str(Path(__file__).resolve().parents[2] / "ask" / "run.sh"),
        "tau-dag",
        "compete",
    ]
    assert [payload["ask_command"][i + 1] for i, item in enumerate(payload["ask_command"]) if item == "--handler"] == [
        "gpt-5.5-high",
        "webkimi",
    ]
    assert {code["code"] for code in payload["failure_codes"]} >= {
        "create_svg_variant_count_invalid",
        "create_svg_variant_handler_count_mismatch",
        "create_svg_variant_handler_family_overlap",
        "create_svg_tau_compile_or_execute_failed",
        "create_svg_visual_gate_not_ready",
    }


