def test_tau_provenance_gate_rejects_local_preview_without_tau_receipts(tmp_path: Path) -> None:
    preview_svg = tmp_path / "ledger-first.svg"
    launch = tmp_path / "launch-receipt.json"
    receipt = tmp_path / "provenance.json"
    preview_svg.write_text('<svg xmlns="http://www.w3.org/2000/svg"><title>preview</title></svg>\n', encoding="utf-8")
    launch.write_text(
        json.dumps(
            {
                "kind": "create_svg.tau_variant_loop_plan.v1",
                "status": "NEEDS_ATTENTION",
                "run_dir": str(tmp_path / "missing-run"),
                "goal": "represent Tau",
                "target": "project-card",
                "target_size": "400x260",
            }
        ),
        encoding="utf-8",
    )

    result = RUNNER.invoke(
        app,
        [
            "tau-provenance-gate",
            str(launch),
            str(preview_svg),
            "--candidate-receipt",
            str(tmp_path / "missing-candidate.json"),
            "--visual-gate-receipt",
            str(tmp_path / "missing-visual.json"),
            "--creator-node-id",
            "handler-gpt-5-5-high",
            "--judge-node-id",
            "judge",
            "--receipt",
            str(receipt),
        ],
    )

    assert result.exit_code == 1
    payload = json.loads(receipt.read_text(encoding="utf-8"))
    assert payload["status"] == "BLOCKED"
    assert payload["failure_code"] == "create_svg_tau_provenance_missing_candidate_receipt"
    assert any("missing-run" in error for error in payload["errors"])


